import{Ft as e,St as t,bt as n,ht as r,qt as i,t as a,vt as o,xt as s,zt as c}from"./chunks/framework.B0CLzZNn.js";import"./chunks/assets.2zH0uHwH.js";var l=JSON.parse(`{"title":"Dify","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configure-model-platform/dify.md","filePath":"v1/guide/configure-model-platform/dify.md","lastUpdated":1793342047000}`),u={name:`guide/configure-model-platform/dify.md`},d={class:`tip custom-block`};function f(a,l,u,f,p,m){let h=c(`NolebasePageProperties`),g=c(`VPNolebaseInlineLinkPreview`),_=c(`NolebaseGitChangelog`);return e(),o(`div`,null,[l[11]||=r(`h1`,{id:`dify`,tabindex:`-1`},[s(`Dify `),r(`a`,{class:`header-anchor`,href:`#dify`,"aria-label":`Permalink to “Dify”`},`​`)],-1),t(h),l[12]||=n(`<p>Dify 是一款开源的大语言模型（LLM）应用开发平台，旨在通过声明式、低代码的方式简化生成式 AI 应用的构建与部署流程。其核心理念在于提供模块化设计、丰富的功能组件（如 AI 工作流、RAG 管道、Agent 框架等）以及对多种大语言模型（如 GPT、Llama3 等）的全面支持，使开发者能够通过简洁的 YAML 文件或可视化界面快速定义应用的 Prompt、上下文和插件等元素 。Dify 强调后端即服务（Backend as Service）和 LLMOps（大型语言模型运维）理念，提供单一 API 或开箱即用的 WebApp，支持从原型到生产的全生命周期管理，同时具备可观测性功能以监控日志和性能，便于持续优化</p><p>我们提供了 <code>dify-adapter</code> 适配器来接入 Dify 应用。</p><h2 id="提示" tabindex="-1">提示 <a class="header-anchor" href="#提示" aria-label="Permalink to “提示”">​</a></h2><p>Dify 的 API 更接近于 LLM 应用层的 API，而不是类似 OpenAI 等平台消息的 API，且 Dify 自维护了对话上下文。由于 ChatLuna 本身就维护了自己的对话上下文，这和 Dify 自维护的对话上下文产生了冲突。这导致 ChatLuna 的 Dify 适配器无法完全兼容现有的 ChatLuna 生态。</p><p>包括 <strong>ChatLuna 的预设系统</strong>，<strong>长期记忆</strong>，<strong>搜索服务</strong>，<strong>知识库</strong> 等都不支持。你需要自行使用 Dify 工作流实现上面的功能。</p><p>ChatLuna 最终选择以兼容的方式来接入 Dify 应用。</p><p>当用户使用 ChatLuna 时，ChatLuna 会根据不同的房间或者配置，创建不同的 Dify 对话，通过 Dify 自带的对话 API 来管理对话。</p><p>可以直接理解为：一个 ChatLuna 房间对应一个 Dify 对话。</p><p>但 ChatLuna 在运行 Dify 工作流时也会传入一些变量，包括用户的历史聊天内容，当前的用户名等，这使得你可以自定义更多的工作流内容，在下文我们会介绍。</p><p>我们建议你在使用 Dify 适配器时，搭建的工作流尽量使用 Dify 的功能。将 ChatLuna 视为一个只传递了输入内容和一些变量给 Dify 的工具即可。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h2><p>前往插件市场，搜索 <code>chatluna-dify-adapter</code> ，安装即可。</p>`,12),r(`div`,d,[l[2]||=r(`p`,{class:`custom-block-title`},`提示`,-1),l[3]||=r(`p`,null,[s(`如果无法正常搜索到 `),r(`code`,null,`chatluna-dify-adapter`),s(` ，则说明官方插件源没有正常更新。 前往 market 插件设置为其他源即可：`)],-1),l[4]||=r(`p`,null,[r(`img`,{src:`/images/markethuanyuan.png`,alt:`market`,width:`2556`,height:`1357`,loading:`lazy`})],-1),l[5]||=r(`p`,null,`以下是推荐的一些插件源：`,-1),r(`ul`,null,[r(`li`,null,[t(g,{href:`https://koishi-registry.yumetsuki.moe/index.json`,target:`_blank`,rel:`noreferrer`},{default:i(()=>[...l[0]||=[s(`https://koishi-registry.yumetsuki.moe/index.json`,-1)]]),_:1})]),r(`li`,null,[t(g,{href:`https://kp.itzdrli.cc`,target:`_blank`,rel:`noreferrer`},{default:i(()=>[...l[1]||=[s(`https://kp.itzdrli.cc`,-1)]]),_:1})])])]),l[13]||=n(`<h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to “配置”">​</a></h2><p>前往你个人部署（或云的）Dify 页面，选择你需要接入的应用。</p><p><img src="/images/image-77.png" alt="alt text" width="1918" height="494" loading="lazy"></p><p>进入应用的配置页面，点击右上角的 API Key：</p><p><img src="/images/image-78.png" alt="alt text" width="1920" height="806" loading="lazy"></p><p>复制 API Key 到适配器的配置页面。</p><p><img src="/images/image-79.png" alt="alt text" width="815" height="248" loading="lazy"></p><p>添加相关的 API Key，并填写应用的名称，选择应用的类型：</p><p><img src="/images/image-80.png" alt="alt text" width="871" height="467" loading="lazy"></p><p>你也可以接入多个应用，点击添加项目，基于上面的步骤添加即可。</p><p>完成后记得点击右上角的保存按钮。</p><h2 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to “使用”">​</a></h2><p>在适配器的配置页面，点击运行按钮，如无误，你应该看不到任何错误 log，那即可转到 ChatLuna 的主插件页面。</p>`,13),r(`p`,null,[l[8]||=s(`在主插件页面，下划到 `,-1),t(g,{href:`./../useful-configurations.html#模版房间选项`},{default:i(()=>[...l[6]||=[s(`模版房间选项`,-1)]]),_:1}),l[9]||=s(`，查看 `,-1),t(g,{href:`./../useful-configurations.html#defaultmodel`},{default:i(()=>[...l[7]||=[s(`defaultModel`,-1)]]),_:1}),l[10]||=s(` 的选项里是否含有 Dify 模型，如果有，则说明你已经成功地接入了 Dify 平台。`,-1)]),l[14]||=n(`<p><img src="/images/image-81.png" alt="alt text" width="1067" height="296" loading="lazy"></p><h2 id="可用变量" tabindex="-1">可用变量 <a class="header-anchor" href="#可用变量" aria-label="Permalink to “可用变量”">​</a></h2><p>ChatLuna 会将以下变量传入 Dify 工作流中：</p><ul><li><code>chatluna_history</code>：当前对话的聊天内容，为 string 格式的 JSON 数组。包含了 role 和 content 两个字段。</li><li><code>chatluna_user_name</code>：当前对话的用户名。</li><li><code>chatluna_user_id</code>：当前对话的用户 ID。</li><li><code>chatluna_conversation_id</code>：当前对话的 ChatLuna 对话 ID</li><li><code>input</code>：用户输入的内容。</li></ul><p>你可以在 Dify 工作流中使用这些变量，来自定义你的工作流。</p>`,5),t(_)])}var p=a(u,[[`render`,f]]);export{l as __pageData,p as default};